-- Categoría 1: Juegos de mesa
(1, 1, 'Catan', 'Juego de estrategia y comercio', 'Catan es un juego de estrategia clásico donde los jugadores compiten por construir asentamientos, ciudades y carreteras en una isla. Cada turno implica comerciar recursos con otros jugadores, haciendo que sea un juego dinámico y social.', 34.99, 'https://via.placeholder.com/300x300?text=Catan', 'Estrategia', NULL, '2-4 jugadores', '1995', 1, 4.8),
(2, 1, 'Carcassonne', 'Juego de colocación de losetas', 'Carcassonne es un juego de construcción de paisajes medievales mediante la colocación de losetas. Los jugadores crean caminos, ciudades y monasterios mientras compiten por puntos. Es un juego accesible pero con profundidad estratégica.', 24.99, 'https://via.placeholder.com/300x300?text=Carcassonne', 'Colocación de losetas', NULL, '2-5 jugadores', '2000', 1, 4.7),
(3, 1, 'Risk', 'Juego de conquista mundial', 'Risk es un juego de estrategia militar donde los jugadores compiten por conquistar el mundo. Cada turno implica mover tropas y construir fortificaciones.', 29.99, 'https://via.placeholder.com/300x300?text=Risk', 'Estrategia', NULL, '2-6 jugadores', '1959', 1, 4.6),
(4, 1, 'Monopoly', 'Juego de finanzas y propiedades', 'Monopoly es un clásico de compra y venta de propiedades. Los jugadores construyen y desarrollan sus propiedades para obtener rentas.', 19.99, 'https://via.placeholder.com/300x300?text=Monopoly', 'Finanzas', NULL, '2-8 jugadores', '1935', 1, 4.5),
(5, 1, 'Dixit', 'Juego de cartas ilustradas', 'Dixit es un juego de creatividad e imaginación. Los jugadores describen imágenes que otros deben adivinar.', 21.99, 'https://via.placeholder.com/300x300?text=Dixit', 'Creatividad', NULL, '3-6 jugadores', '2008', 1, 4.7),
(6, 1, '7 Wonders', 'Juego de civilizaciones', 'Construye una civilización y compite por puntos. Cada jugador construye una civilización y gana puntos por sus logros.', 27.99, 'https://via.placeholder.com/300x300?text=7+Wonders', 'Civilización', NULL, '2-7 jugadores', '2010', 1, 4.6),
(7, 1, 'Aventureros al Tren', 'Juego de trenes y rutas', 'Conecta ciudades y gana puntos. Los jugadores construyen rutas y conectan ciudades.', 32.99, 'https://via.placeholder.com/300x300?text=Aventureros+al+Tren', 'Rutas', NULL, '2-5 jugadores', '2004', 1, 4.8),
(8, 1, 'Jungle Speed', 'Juego de reflejos', 'Sé el más rápido en atrapar el tótem. Los jugadores deben atrapar el tótem antes que el otro.', 14.99, 'https://via.placeholder.com/300x300?text=Jungle+Speed', 'Reflejos', NULL, '2-10 jugadores', '1997', 1, 4.4),
(9, 1, 'Virus!', 'Juego de cartas de virus', 'Compite por erradicar virus en tu cuerpo. Los jugadores deben atrapar virus antes que el otro.', 13.99, 'https://via.placeholder.com/300x300?text=Virus', 'Cartas', NULL, '2-6 jugadores', '2015', 1, 4.5),
(10, 1, 'Código Secreto', 'Juego de palabras y espías', 'Adivina las palabras clave de tu equipo. Los jugadores deben adivinar palabras clave.', 18.99, 'https://via.placeholder.com/300x300?text=Codigo+Secreto', 'Palabras', NULL, '2-8 jugadores', '2015', 1, 4.7),
-- Categoría 2: Juegos PC
(11, 2, 'Cyberpunk 2077', 'RPG futurista', 'Cyberpunk 2077 es un RPG de acción en primera persona ambientado en el futuro distópico de 2077. Crea tu personaje y sumérgete en la megaciudad de Night City, donde tus acciones y decisiones moldean tu historia única.', 29.99, 'https://via.placeholder.com/300x300?text=Cyberpunk+2077', 'RPG', 'CD Projekt Red', '1 jugador', '2020', 1, 4.5),
(12, 2, 'Baldur''s Gate 3', 'RPG táctico', 'Baldur''s Gate 3 es un RPG de rol táctico que trae la magia de Dungeons & Dragons al mundo digital. Con miles de posibilidades narrativas y batallas estratégicas, cada decisión importa en esta épica aventura.', 49.99, 'https://via.placeholder.com/300x300?text=Baldurs+Gate+3', 'RPG', 'Larian Studios', '1-4 jugadores', '2023', 1, 4.9),
