-- Categoría 5: Juegos PlayStation 5
(41, 5, 'Marvel''s Spider-Man 2 (PS5)', 'Aventura de superhéroes en Nueva York', 'Experiencia una historia épica de Spider-Man con gráficos de siguiente generación. Controla a Peter Parker y Miles Morales mientras proteges Nueva York de nuevas amenazas en este emocionante juego de acción y aventura.', 69.99, 'https://via.placeholder.com/300x300?text=Spider-Man+2', 'Acción, Aventura, Superhéroes', 'Insomniac Games', NULL, '2023', 1, 4.8),
(42, 5, 'Demon''s Souls (PS5)', 'RPG de acción desafiante', 'Demon''s Souls es un remake espectacular del clásico de PS3. Enfrenta enemigos desafiantes, mejora tus habilidades y derrota poderosos jefes en este juego que requiere habilidad, estrategia y perseverancia.', 49.99, 'https://via.placeholder.com/300x300?text=Demons+Souls', 'RPG de acción, Souls-like', 'Bluepoint Games', NULL, '2020', 1, 4.7),
(43, 5, 'Ratchet & Clank: Rift Apart', 'Aventura interdimensional', 'Viaja entre dimensiones con Ratchet y Clank en esta entrega exclusiva de PS5.', 59.99, 'https://via.placeholder.com/300x300?text=Ratchet+Clank', 'Aventura', 'Insomniac Games', NULL, '2021', 1, 4.8),
(44, 5, 'Returnal', 'Roguelike de ciencia ficción', 'Enfrenta ciclos infinitos en un planeta alienígena hostil.', 49.99, 'https://via.placeholder.com/300x300?text=Returnal', 'Roguelike', 'Housemarque', NULL, '2021', 1, 4.6),
(45, 5, 'Gran Turismo 7', 'Simulación de carreras', 'Compite en circuitos realistas con una gran variedad de autos.', 69.99, 'https://via.placeholder.com/300x300?text=Gran+Turismo+7', 'Simulación', 'Polyphony Digital', NULL, '2022', 1, 4.7),
(46, 5, 'Horizon Forbidden West', 'Aventura de mundo abierto', 'Explora un mundo postapocalíptico lleno de máquinas.', 69.99, 'https://via.placeholder.com/300x300?text=Horizon+FW', 'Aventura', 'Guerrilla Games', NULL, '2022', 1, 4.8),
(47, 5, 'Sackboy: Una aventura a lo grande', 'Plataformas cooperativo', 'Acompaña a Sackboy en una aventura divertida y colorida.', 59.99, 'https://via.placeholder.com/300x300?text=Sackboy', 'Plataformas', 'Sumo Digital', NULL, '2020', 1, 4.5),
(48, 5, 'Ghost of Tsushima: Director''s Cut', 'Acción samurái', 'Vive la historia de Jin Sakai en la isla de Tsushima.', 59.99, 'https://via.placeholder.com/300x300?text=Ghost+of+Tsushima', 'Acción', 'Sucker Punch', NULL, '2021', 1, 4.9),
